  ('ea198517-04f3-5886-a89d-18f629c757fb', 'Masoor Dal Chawal', 'Split red-lentil dal. Goes with rice and a glass of buttermilk.', 'North Indian', null, 'vegan', 'active', 230, 'admin'),
  ('1208759f-fda3-268b-2d40-c758802d12a3', 'Masala Daliya Bowl', 'Broken-wheat and moong dal daliya. Goes with vegetable raita.', 'North Indian', null, 'vegetarian', 'active', 220, 'admin'),
  ('1aa9f4f2-ef2c-5b94-509e-e214b970c155', 'Tomato Sprouts Rice Bowl', 'Tomato rice with moong sprouts. Goes with a bowl of curd.', 'South Indian', null, 'vegan', 'active', 210, 'admin'),
  ('1c4ab7b4-d702-ba9a-9323-c0bf870e20ca', 'Paneer Kathi Roll Meal', 'A whole-wheat paneer-tikka roll — a wholesome one-hand lunch.', 'North Indian', null, 'vegetarian', 'active', 200, 'admin'),
  ('0d67220f-6b6e-23db-9985-32666a7e107b', 'Rajma with Barley', 'Rajma curry. Goes with boiled barley and mixed-vegetable raita. Needs overnight soaking.', 'North Indian', null, 'vegetarian', 'active', 190, 'admin'),
  ('011966c2-0533-c789-64da-c34b464cbab9', 'Mexican Bean Wrap Meal', 'A rajma-stuffed wrap. Goes with a bowl of carrot soup.', 'Mexican', null, 'vegetarian', 'active', 180, 'admin'),
  ('d5880055-a6cf-80f0-d6e1-5af53ecc5afe', 'Green Gram Dal Thali', 'Whole green-gram dal. Goes with brown rice and mixed-vegetable raita.', 'North Indian', null, 'vegan', 'active', 170, 'admin'),
  ('9166f0b4-f605-2423-95ee-28a2e8d391a8', 'Matki Usal Meal', 'Sprouted moth-bean usal. Goes with multigrain roti and a fresh salad. Needs sprouting.', 'Maharashtrian', null, 'vegan', 'active', 160, 'admin'),
  ('d3f01b6f-794c-c805-3efa-81607e677651', 'Brown Rice Pulao Meal', 'Vegetable brown-rice pulao. Goes with kadhi.', 'North Indian', null, 'vegan', 'active', 150, 'admin'),
  ('d283bb6c-03ef-d3e8-c4d8-eed172f7fe69', 'Paneer Sweet Corn Roti', 'Paneer and sweet-corn sabji. Goes with multigrain roti.', 'North Indian', null, 'vegetarian', 'active', 140, 'admin'),
  ('2adb6fd4-7b59-acb9-6160-d3e377105fb3', 'Carrot Pumpkin Soup Dinner', 'A protein-rich carrot-pumpkin lentil soup — a light one-bowl dinner.', 'Continental', null, 'vegan', 'active', 130, 'admin'),
  ('f94cc25a-59da-3f94-6138-cef466824588', 'Rajma Salad Bowl', 'A boiled-rajma salad. Goes with a bowl of curd. Needs overnight soaking.', 'North Indian', null, 'vegan', 'active', 120, 'admin'),
  ('3a4c6fd2-77ea-ad5e-dff0-400bfb3325a4', 'Paneer Tomato Salad Dinner', 'A light high-protein paneer-and-tomato salad.', 'North Indian', null, 'vegetarian', 'active', 110, 'admin'),
  ('5e91692f-b0b6-ba0e-4fdf-6cc2e2ab1d8f', 'Moong Dosa & Chutney', 'Protein moong dal dosa. Goes with tomato chutney.', 'South Indian', null, 'vegan', 'active', 100, 'admin'),
  ('6e6d7534-01cd-3431-471a-11d546bdd058', 'Lauki Soup Dinner', 'A very light lauki-tomato soup. Goes with a boiled-moong salad.', 'North Indian', null, 'vegan', 'active', 90, 'admin'),
  ('46dd95f9-ec26-082c-d091-15f37d6f8d47', 'Spinach Soup & Cheela', 'Spinach-carrot soup. Goes with a moong dal cheela.', 'Continental', null, 'vegan', 'active', 80, 'admin'),
  ('3c974629-35f8-e919-8b7c-3c94a561ce00', 'Methi Moong Dal Meal', 'Moong dal with fenugreek. Goes with boiled barley.', 'North Indian', null, 'vegan', 'active', 70, 'admin'),
  ('0e818569-e11f-f6b9-837d-79205bd180b5', 'Quinoa Khichdi Bowl', 'Quinoa-moong khichdi. Goes with sautéed mushrooms and pudina raita.', 'North Indian', null, 'vegetarian', 'active', 60, 'admin'),
  ('1634394c-1994-edc3-9313-dfd7c1a93be2', 'Pesarattu & Dal Soup', 'Andhra green-gram dosa. Goes with a bowl of dal soup.', 'South Indian', null, 'vegan', 'active', 50, 'admin'),
  ('69f44a73-84b2-f95c-a029-692bb7534ae1', 'Kerala Veg Stew', 'A coconut-milk vegetable stew — a light, soupy dinner.', 'South Indian', null, 'vegetarian', 'active', 40, 'admin'),
  ('b164c199-9dd8-991b-541b-cc175629e60d', 'Quinoa Lentil Khichdi Bowl', 'Quinoa-and-lentil khichdi. Goes with grilled paneer.', 'North Indian', null, 'vegan', 'active', 30, 'admin'),
  ('cdbb0fa8-eeb3-e60d-e288-ea336e011df8', 'Paneer & Barley Soup', 'Sautéed paneer with capsicum. Goes with a bowl of barley dal soup.', 'North Indian', null, 'vegetarian', 'active', 20, 'admin'),
  ('99439faf-7e01-8f39-5916-3cddbe908fad', 'Grilled Veg & Soup', 'Char-grilled vegetables. Goes with a bowl of carrot soup.', 'Continental', null, 'vegan', 'active', 10, 'admin')
